var codex_target_host_default = `/* DSH input-trigger 0.2.1-alpha.2 MenuView: exact item/itemIcon/name/description DOM.
 * Only our public candidate.icon supplies data-codex-cu-candidate. All row rules
 * also require the pinned classes and direct-child structure; other sources,
 * section headers, loading rows and MenuSurface are outside these selectors.
 * Codex source geometry: JHc / YAi / hYc and original-css-rules.json.
 */
@supports selector(:has(*)) {
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) {
    --codex-target-host-artwork-size: var(--icon-size, 16px);
    --codex-target-host-leading-size: var(--icon-leading-size, 16px);
    --codex-target-host-text-gap: var(--spacing-menu-row-content, calc(var(--spacing, .25rem) * 2));
    --codex-target-host-leading-gap: var(--spacing-menu-item-content, calc(var(--spacing, .25rem) * 1.5));
    box-sizing: border-box;
    min-height: var(--app-menu-item-height, 0px);
    flex-shrink: 0;
    overflow: hidden;
    gap: var(--codex-target-host-text-gap);
    padding: var(--suggestion-menu-item-padding, var(--app-menu-item-padding, var(--padding-row-y, var(--spacing, .25rem)) var(--padding-row-x, calc(var(--spacing, .25rem) * 2))));
    border-radius: var(--suggestion-menu-item-radius, var(--radius-xl, .75rem));
    color: var(--color-text, var(--dsw-alias-label-primary));
    font-family: var(--font-ui-family, inherit);
    font-size: var(--text-sm, 13px);
    line-height: var(--text-sm--line-height, calc(1.25 / .875));
    text-align: start;
    opacity: var(--opacity-menu-row, .75);
  }

  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate])[aria-selected="true"],
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]):focus {
    background: var(--color-background-primary-ghost-hover, var(--dsw-alias-interactive-bg-hover));
    opacity: 1;
  }

  /* YAi's leading-icon wrapper uses a separate gap from hYc's label/detail. */
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) > ._3e4SsG_itemIcon {
    width: var(--codex-target-host-leading-size);
    height: var(--codex-target-host-leading-size);
    margin-inline-end: calc(var(--codex-target-host-leading-gap) - var(--codex-target-host-text-gap));
    color: inherit;
  }

  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) > ._3e4SsG_itemName,
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) > ._3e4SsG_itemDescription {
    min-width: 0;
    max-width: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Native app/browser alias: source keeps label width, detail fills the rest. */
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) > ._3e4SsG_itemName {
    flex: 0 0 auto;
  }

  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate]) > ._3e4SsG_itemDescription {
    flex: 1 1 auto;
    color: var(--color-codex-description, var(--dsw-alias-label-tertiary));
    font-size: inherit;
    line-height: inherit;
    text-align: start;
  }

  /* uci/hYc's browser-tab branch allows both label and URL detail to shrink. */
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate-label-shrink]) > ._3e4SsG_itemName,
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate-label-shrink]) > ._3e4SsG_itemDescription {
    flex: 0 1 auto;
  }

  /* Complete source browser geometry branch; electron remains the default. */
  [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate][data-codex-cu-candidate-window-type="browser"]) {
    --codex-target-host-leading-size: var(--icon-leading-size, calc(var(--spacing, .25rem) * 5));
    --codex-target-host-text-gap: var(--spacing-menu-row-content, calc(var(--spacing, .25rem) * 3));
    --codex-target-host-leading-gap: var(--spacing-suggestion-menu-leading, var(--codex-target-host-text-gap));
    min-height: var(--app-menu-item-height, calc(var(--spacing, .25rem) * 9));
    padding: var(--suggestion-menu-item-padding, calc(var(--spacing, .25rem) * 1.5) calc(var(--spacing, .25rem) * 2));
    font-size: var(--text-sm, .875rem);
  }

  @media (pointer: coarse) {
    [data-trigger-menu] [role="listbox"] > button._3e4SsG_item[role="option"]:has(> ._3e4SsG_itemIcon > [data-codex-cu-candidate][data-codex-cu-candidate-window-type="browser"]) {
      min-height: var(--app-menu-item-height, calc(var(--spacing, .25rem) * 10));
    }
  }
}
`;

