var preview_alignment_default = "/* Scoped preview surfaces retain the host's palette and input ownership. */\n.tx-cu-native-preview > .tx-cu-live-meta { min-height: 34px; gap: 12px; padding: 7px 10px; }\n.tx-cu-live-heading { display: flex; flex-direction: column; gap: 1px; min-width: 0; }\n.tx-cu-live-heading strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--cu-text); font-size: 12px; font-weight: 500; }\n.tx-cu-live-control { flex-shrink: 0; font-size: 10px; }\n.tx-cu-native-preview .tx-cu-reconnect { min-height: 28px; padding: 4px 8px; font-size: 11px; }\n.tx-cu-floating .tx-cu-preview-open:hover:not(:disabled) { background: #ffffff0a; }\n.tx-cu-floating .tx-cu-preview-card[data-connection=error] .tx-cu-preview-open::before,\n.tx-cu-floating .tx-cu-preview-card[data-connection=closed] .tx-cu-preview-open::before { opacity: 1; }\n.tx-cu-floating > .tx-cu-error { border-radius: 7px; padding: 5px 7px; background: var(--cu-bg); }\n.tx-cu-floating footer > span[data-connection=error],\n.tx-cu-floating footer > span[data-connection=closed] { color: var(--cu-danger); }\n.tx-cu-window-picker { width: min(500px, calc(100vw - 32px)); }\n.tx-cu-window-picker > header strong { font-size: 14px; }\n.tx-cu-window-picker > p { margin: 6px 0 14px; }\n.tx-cu-window-picker .tx-cu-share-list { gap: 2px; }\n.tx-cu-window-picker .tx-cu-share-list button { min-height: 54px; padding: 9px 8px; }\n.tx-cu-window-picker .tx-cu-share-window-icon { width: 30px; height: 30px; }\n.tx-cu-window-picker .tx-cu-share-window-info strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.tx-cu-share-feedback { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 8px 0; padding: 9px 10px; border: 1px solid var(--cu-line); border-radius: 8px; }\n.tx-cu-share-feedback p { min-width: 0; margin: 0; font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }\n.tx-cu-share-feedback button { flex-shrink: 0; }\n@media (max-width: 400px) {\n  .tx-cu-live-control { max-width: 45%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .tx-cu-window-picker { padding: 14px; }\n  .tx-cu-window-picker footer { gap: 10px; }\n  .tx-cu-window-picker footer small { min-width: 0; font-size: 10px; }\n}\n\n/* Actual app content has no second page header or framed preview card. */\n.tx-cu-pane-app { display: flex; flex-direction: column; padding: 0; overflow: hidden; }\n.tx-cu-pane-app > .tx-cu-native-preview.is-content { flex: 1 1 0; min-height: 0; margin: 0; border: 0; border-radius: 0; background: transparent; }\n.tx-cu-pane-app > .tx-cu-pane-support { flex: 0 1 auto; max-height: 45%; padding-inline: 12px; overflow: auto; }\n\n/* Native home surface: local-conversation-thread Iw/Bw/Lw, UTF-8\n   134495..142429. The PNG transport remains an explicit adapter. */\n.tx-cu-native-preview.codex-cu-native-surface {\n  position: relative;\n  display: grid;\n  grid-template-columns: repeat(1, minmax(0, 1fr));\n  grid-template-rows: repeat(1, minmax(0, 1fr));\n  width: 100%;\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  overflow: visible;\n}\n.codex-cu-native-surface > .codex-cu-native-presentation {\n  grid-column-start: 1;\n  grid-row-start: 1;\n  align-self: start;\n  justify-self: center;\n  width: fit-content;\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  text-align: start;\n  transform-origin: top right;\n  line-height: 0;\n}\n.codex-cu-native-surface > button.codex-cu-native-presentation { cursor: var(--cursor-interaction); }\n.codex-cu-native-surface > button.codex-cu-native-presentation:hover:not(:disabled) { background: transparent; }\n.codex-cu-native-surface > button.codex-cu-native-presentation:focus-visible {\n  outline: 2px solid var(--color-ring);\n  outline-offset: 0;\n}\n.codex-cu-native-surface .codex-cu-native-image {\n  display: block;\n  width: auto;\n  height: auto;\n  margin-inline-start: auto;\n  object-fit: contain;\n  filter: drop-shadow(var(--drop-shadow-md));\n  -webkit-user-select: none;\n  user-select: none;\n  -webkit-user-drag: none;\n  background: transparent;\n}\n.codex-cu-native-surface > button.codex-cu-native-presentation:focus-visible .codex-cu-native-image {\n  filter: brightness(.95) drop-shadow(var(--drop-shadow-md));\n}\n@media (hover: hover) {\n  .codex-cu-native-surface > button.codex-cu-native-presentation:hover .codex-cu-native-image { filter: brightness(.95) drop-shadow(var(--drop-shadow-md)); }\n}\n.codex-cu-native-surface[data-native-ready=false] > .codex-cu-native-presentation { visibility: hidden; }\n.codex-cu-native-surface.is-stacked { width: fit-content; }\n.codex-cu-native-surface.is-stacked > .codex-cu-native-presentation { justify-self: end; }\n\n/* Fw/Iw/Bw native home stack. No native pinned-window material is emulated. */\n.codex-cu-native-home {\n  position: relative;\n  display: grid;\n  grid-template-columns: repeat(1, minmax(0, 1fr));\n  grid-template-rows: repeat(1, minmax(0, 1fr));\n  flex-shrink: 0;\n  margin-bottom: calc(var(--spacing) * 2);\n  pointer-events: auto;\n}\n.codex-cu-native-home[hidden] { display: none; }\n.codex-cu-native-stack {\n  position: relative;\n  display: grid;\n  grid-template-columns: repeat(1, minmax(0, 1fr));\n  grid-template-rows: repeat(1, minmax(0, 1fr));\n}\n.codex-cu-native-stack[data-native-invisible=true] { visibility: hidden; }\n.codex-cu-native-home-anchor {\n  position: absolute;\n  inset-block: 0;\n  visibility: visible;\n  pointer-events: none;\n}\n.codex-cu-native-stack-frame {\n  grid-column-start: 1;\n  grid-row-start: 1;\n  align-self: start;\n  justify-self: end;\n  width: fit-content;\n  transform-origin: top right;\n}\n\n.tx-cu-settings-dialog { width: min(560px, calc(100vw - 32px)); max-height: calc(100dvh - 48px); overflow: auto; }\n.tx-cu-settings-dialog .tx-cu-setup { margin-top: 4px; border-top: 0; }\n";

